16	package org.springframework.samples.petclinic.model;
17	
18	import org.springframework.core.style.ToStringCreator;
19	
20	import jakarta.persistence.*;
21	import jakarta.validation.constraints.Email;
22	import jakarta.validation.constraints.NotEmpty;
23	import jakarta.validation.constraints.Pattern;
24	
25	import java.time.LocalDate;
26	import java.util.*;
27	
28	/**
29	 * Simple JavaBean domain object representing an owner.
30	 *
31	 * @author Ken Krebs
32	 * @author Juergen Hoeller
33	 * @author Sam Brannen
34	 * @author Michael Isvy
35	 */
36	@Entity
37	@Table(name = "owners")
38	public class Owner extends Person {
39	    @Column(name = "address")
40	    @NotEmpty
41	    private String address;
42	
43	    @Column(name = "city")
44	    @NotEmpty
45	    private String city;
46	
47	    @Column(name = "telephone")
48	    @NotEmpty
49	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 format")
50	    private String telephone;
51	
52	    @Column(name = "email")
53	    @Email
54	    private String email;
55	
56	    @Column(name = "registration_date")
57	    private LocalDate registrationDate;
58	
59	    @Column(name = "customer_code")
60	    private String customerCode;
61	
62	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
63	    private Set<Pet> pets;
64	
65	    public String getAddress() {
66	        return this.address;
67	    }
68	
69	    public void setAddress(String address) {
70	        this.address = address;
71	    }
72	
73	    public String getCity() {
74	        return this.city;
75	    }
76	
77	    public void setCity(String city) {
78	        this.city = city;
79	    }
80	
81	    public String getTelephone() {
82	        return this.telephone;
83	    }
84	
85	    public void setTelephone(String telephone) {
86	        this.telephone = telephone;
87	    }
88	
89	    public String getEmail() {
90	        return this.email;
91	    }
92	
93	    public void setEmail(String email) {
94	        this.email = email;
95	    }
96	
97	    public LocalDate getRegistrationDate() {
98	        return this.registrationDate;
99	    }
100	
101	    public void setRegistrationDate(LocalDate registrationDate) {
102	        this.registrationDate = registrationDate;
103	    }
104	
105	    public String getCustomerCode() {
106	        return this.customerCode;
107	    }
108	
109	    public void setCustomerCode(String customerCode) {
110	        this.customerCode = customerCode;
111	    }
112	
113	    protected Set<Pet> getPetsInternal() {
114	        if (this.pets == null) {
115	            this.pets = new HashSet<>();
116	        }
117	        return this.pets;
118	    }
119	
120	    protected void setPetsInternal(Set<Pet> pets) {
121	        this.pets = pets;
122	    }
123	
124	    public List<Pet> getPets() {
125	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
126	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
127	        return Collections.unmodifiableList(sortedPets);
128	    }
129	
130	    public void setPets(List<Pet> pets) {
131	        this.pets = new HashSet<>(pets);
132	    }
133	
134	    public void addPet(Pet pet) {
135	        getPetsInternal().add(pet);
136	        pet.setOwner(this);
137	    }
138	
139	    /**
140	     * Return the Pet with the given name, or null if none found for this Owner.
141	     *
142	     * @param name to test
143	     * @return true if pet name is already in use
144	     */
145	    public Pet getPet(String name) {
146	        return getPet(name, false);
147	    }
148	
149	    /**
150	     * Return the Pet with the given name, or null if none found for this Owner.
151	     *
152	     * @param name to test
153	     * @return true if pet name is already in use
154	     */
155	    public Pet getPet(String name, boolean ignoreNew) {
156	        name = name.toLowerCase();
157	        for (Pet pet : getPetsInternal()) {
158	            if (!ignoreNew || !pet.isNew()) {
159	                String compName = pet.getName();
160	                compName = compName.toLowerCase();
161	                if (compName.equals(name)) {
162	                    return pet;
163	                }
164	            }
165	        }
166	        return null;
167	    }
168	
169	    public Pet getPet(Integer petId) {
170	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
171	    }
172	
173	    @Override
174	    public String toString() {
175	        return new ToStringCreator(this)
176	
177	            .append("id", this.getId())
178	            .append("new", this.isNew())
179	            .append("lastName", this.getLastName())
180	            .append("firstName", this.getFirstName())
181	            .append("address", this.address)
182	            .append("city", this.city)
183	            .append("telephone", this.telephone)
184	            .append("email", this.email)
185	            .toString();
186	    }
187	}
