4	import java.util.List;
5	
6	import net.officefloor.plugin.variable.Out;
7	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
8	import org.springframework.samples.petclinic.rest.escalation.MissingOwnerFieldsException;
9	import org.springframework.web.bind.annotation.RequestBody;
10	
11	/**
12	 * Rejects a create-owner request that is missing or blank in any required field
13	 * (firstName, lastName, address, city, telephone) before {@link BuildOwner} runs,
14	 * publishing the body for later steps. Binds the request body once for the pipeline.
15	 */
16	public class RequireOwnerFields {
17	
18	    public void service(@RequestBody OwnerFieldsDto request, Out<OwnerFieldsDto> validated)
19	            throws MissingOwnerFieldsException {
20	        List<String> missing = new ArrayList<>();
21	        if (isBlank(request.getFirstName())) {
22	            missing.add("firstName");
23	        }
24	        if (isBlank(request.getLastName())) {
25	            missing.add("lastName");
26	        }
27	        if (isBlank(request.getAddress())) {
28	            missing.add("address");
29	        }
30	        if (isBlank(request.getCity())) {
31	            missing.add("city");
32	        }
33	        if (isBlank(request.getTelephone())) {
34	            missing.add("telephone");
35	        }
36	        if (!missing.isEmpty()) {
37	            throw new MissingOwnerFieldsException(missing);
38	        }
39	        validated.set(request);
40	    }
41	
42	    private static boolean isBlank(String value) {
43	        return value == null || value.isBlank();
44	    }
45	}
