3	/**
4	 * Shared telephone canonicalization for the create-owner pipeline: reduces a telephone to
5	 * its E.164 form so validation, uniqueness checks and storage all compare the same value.
6	 */
7	final class OwnerTelephones {
8	
9	    private OwnerTelephones() {
10	    }
11	
12	    /**
13	     * Canonicalizes {@code telephone} to E.164 (a leading {@code '+'} followed by 8 to 15
14	     * digits), or returns {@code null} when it cannot form a valid E.164 number.
15	     *
16	     * <p>Spaces, dashes and brackets are stripped. A leading {@code '+'} keeps the given
17	     * country code; otherwise country code {@code +61} is assumed and a single leading
18	     * {@code '0'} is dropped from the national digits. So {@code "0412 345 678"} becomes
19	     * {@code "+61412345678"} and {@code "+64 21 123 456"} becomes {@code "+6421123456"}.
20	     */
21	    static String toE164(String telephone) {
22	        if (telephone == null) {
23	            return null;
24	        }
25	        String cleaned = telephone.replaceAll("[\\s()\\-]", "");
26	        String digits;
27	        if (cleaned.startsWith("+")) {
28	            digits = cleaned.substring(1);
29	        }
30	        else {
31	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
32	            digits = "61" + national;
33	        }
34	        if (!digits.matches("\\d{8,15}")) {
35	            return null;
36	        }
37	        return "+" + digits;
38	    }
39	}
