3	import java.util.Locale;
4	import java.util.regex.Pattern;
5	
6	/**
7	 * Shared email handling for the owner pipelines: normalizes an address to its canonical
8	 * lower-cased form so validation, storage and the response all use the same value.
9	 */
10	final class OwnerEmails {
11	
12	    /** A single {@code @} separating a non-empty local part from a dotted domain. */
13	    private static final Pattern EMAIL = Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
14	
15	    private OwnerEmails() {
16	    }
17	
18	    /** Trimmed, lower-cased form of {@code email}; {@code null} stays {@code null}. */
19	    static String normalize(String email) {
20	        return email == null ? null : email.trim().toLowerCase(Locale.ROOT);
21	    }
22	
23	    /** Whether {@code email} is a syntactically valid address. */
24	    static boolean isValid(String email) {
25	        return email != null && EMAIL.matcher(email).matches();
26	    }
27	}
